  if(s.id===1&&(!s.repeatK||!s.dialysis))return this.error('renal-handover','Include repeat potassium monitoring and a nephrology / dialysis plan.',0);
  if(s.id!==3&&s.id!==4){if(!s.commandsChecked)return this.error('commands-first','Assess response to verbal commands before choosing temperature care.',0);const items=[{k:'SpO₂',v:d.spo2,u:'%',ok:d.spo2>=90&&d.spo2<=98,target:'90–98 %',note:'AHA 2025 widened the lower limit (2020: 92–98 %). Avoid hypoxemia and hyperoxia.'},{k:'MAP',v:d.map,u:'mmHg',ok:d.map>=65,target:'≥65 mmHg',note:'Avoid hypotension (SBP <90, MAP <65).'},{k:'PaCO₂',v:d.co2,u:'mmHg',ok:d.co2>=35&&d.co2<=45,target:'35–45 mmHg',note:'Normocapnia unless severe acidemia.'}];
   if(!s.conscious){items.push({k:'Temperature',v:d.temp,u:'°C',ok:d.temp>=32&&d.temp<=37.5,target:'32–37.5 °C',note:'AHA 2025: temperature control 32–37.5 °C (2020: 32–36 °C) and actively prevent fever.'});items.push({k:'Duration',v:d.hours,u:'h',ok:d.hours>=36,target:'≥36 h',note:'AHA 2025: maintain for at least 36 h (2020: at least 24 h).'});}
   s.postReview=items;const wrong=items.filter(i=>!i.ok);if(wrong.length){this.error('post-targets',`Post-ROSC targets to review (AHA 2025): ${wrong.map(i=>`${i.k} ${i.v||'—'} ${i.u} → target ${i.target}`).join(' · ')}`,0);s.post=true;this.log('post','Handover completed, but some post-arrest targets need review — see the debrief.','warn');this.end('completed');return true;}}
